import{_ as t,o,c as a,ag as d}from"./chunks/framework.HG0H2VLS.js";const g=JSON.parse('{"title":"SeatingHeader — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/patterns/SeatingHeader/SeatingHeader.figma-notes.md","filePath":"public/demos/src/patterns/SeatingHeader/SeatingHeader.figma-notes.md"}'),n={name:"public/demos/src/patterns/SeatingHeader/SeatingHeader.figma-notes.md"};function r(s,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="seatingheader-—-figma-notes" tabindex="-1">SeatingHeader — Figma Notes <a class="header-anchor" href="#seatingheader-—-figma-notes" aria-label="Permalink to &quot;SeatingHeader — Figma Notes&quot;">​</a></h1><p><strong>Tier:</strong> Pattern <strong>Built:</strong> 2026-08-26 (Seating Planner module, wave 6) <strong>Files:</strong> <code>SeatingHeader.css</code>, <code>SeatingHeader.html</code>, <code>SeatingHeader.js</code>, <code>SeatingHeader.figma.ts</code>, <code>SeatingHeader.figma-notes.md</code><strong>Composes:</strong> Button (base, <code>--sm</code>, <code>--icon --xs</code>, <code>--icon --2xs</code> via RoomCard), Toggle (<code>toggle--xs</code>, label-less), RoomCard (one per plan) <strong>JS:</strong> <code>SeatingHeader.js</code> (drag-to-scroll for the plans carousel) + <code>Toggle.js</code></p><h2 id="figma-node" tabindex="-1">Figma Node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma Node&quot;">​</a></h2><ul><li><strong>File key:</strong> <code>Lus07xi8pPXLN87sQIyrEt</code> (Affino AI — Design System)</li><li><strong>Page:</strong> Seat Planner (<code>3087:5050</code>)</li><li><strong>Component set:</strong> <code>3474:90519</code></li></ul><blockquote><p><strong>Figma calls this component <code>Header</code>.</strong> It is filed as <strong>SeatingHeader</strong> because <code>src/patterns/Header</code> already exists and is a completely different component (the AI-Chat header, node <code>68:5443</code>). Worth renaming the Figma component to <code>Seating Header</code> so the two are not confusable in the property panel or in Code Connect.</p></blockquote><h2 id="variant-matrix-4-variants" tabindex="-1">Variant matrix (4 variants) <a class="header-anchor" href="#variant-matrix-4-variants" aria-label="Permalink to &quot;Variant matrix (4 variants)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Type</th><th>Device</th><th>Node</th><th>Figma size</th><th>CSS</th></tr></thead><tbody><tr><td>Pattern</td><td>Has Plans</td><td>Desktop</td><td><code>3474:90518</code></td><td>1552×288</td><td>full markup</td></tr><tr><td>Pattern</td><td>Has Plans</td><td>Mobile</td><td><code>3484:186300</code></td><td>392×317</td><td><code>@media (max-width: 767px)</code></td></tr><tr><td>Pattern</td><td>No Plans</td><td>Desktop</td><td><code>3474:90517</code></td><td>1552×99</td><td><code>__bar</code> only</td></tr><tr><td>Pattern</td><td>No Plans</td><td>Mobile</td><td><code>3484:186449</code></td><td>392×146</td><td><code>__bar</code> only + media query</td></tr></tbody></table><p><code>Tier</code> is single-valued (<code>Pattern</code>). Note that Device is implemented as <strong>two</strong> breakpoints, not one — the toolbar reverts at 1024px while everything else reverts at 768px. See <em>The toolbar has its own breakpoint</em>.</p><h3 id="the-type-axis-is-data-not-css" tabindex="-1">The Type axis is data, not CSS <a class="header-anchor" href="#the-type-axis-is-data-not-css" aria-label="Permalink to &quot;The Type axis is data, not CSS&quot;">​</a></h3><p><code>No Plans</code> is the event bar <strong>on its own</strong>; <code>Has Plans</code> adds the room selector and the toolbar. Confirmed structurally, not inferred: <code>get_metadata</code> on <code>3474:90517</code> returns an <code>Event-Info-Bar</code> and nothing else, and its bar is byte-identical to Has Plans&#39; — same 900px details block, same <code>Item</code> wrapper, same 128/116 buttons. The No Plans heights (99 desktop, 146 mobile) are exactly the Has Plans bar heights.</p><p>So which one renders is markup the caller supplies and there are <strong>no Type modifiers</strong>. This is the <strong>fifth</strong> component in this module where that holds — RoomCard, TableCard, TableDetail and Unassigned all did the same.</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.seating-header                     root: bg, 1px border, radius-lg, overflow hidden, fluid</span></span>
<span class="line"><span>├── .seating-header__bar            Event-Info-Bar   — border-b</span></span>
<span class="line"><span>│   ├── .seating-header__details      Event-Details  — fluid (Figma 900px)</span></span>
<span class="line"><span>│   │   ├── .seating-header__title-row  Title-Row    — title + swap Button</span></span>
<span class="line"><span>│   │   └── .seating-header__meta       User Details — &lt;ul&gt;, 3 facts, wraps</span></span>
<span class="line"><span>│   └── .seating-header__actions      Global-Actions — Copy Plans / New Plan</span></span>
<span class="line"><span>├── .seating-header__rooms          Room-Selector-Bar (a Figma SLOT) — border-b, carousel</span></span>
<span class="line"><span>│   └── .room-card …                  one RoomCard per plan</span></span>
<span class="line"><span>└── .seating-header__toolbar        Toolbar — no border</span></span>
<span class="line"><span>    ├── .seating-header__toolbar-actions</span></span>
<span class="line"><span>    │   ├── .seating-header__room       room name + unassigned count</span></span>
<span class="line"><span>    │   ├── .seating-header__toggle-group  Toggle + &quot;Show unassigned&quot;</span></span>
<span class="line"><span>    │   ├── .seating-header__divider    16px hairline</span></span>
<span class="line"><span>    │   └── .seating-header__buttons    Room Layout / Add Table / Export</span></span>
<span class="line"><span>    └── .seating-header__more         the kebab — a real &lt;button&gt;</span></span></code></pre></div><p>Figma splits <code>Toolbar-Actions</code> into two equal <code>flex-1</code> columns (537px each in a 1468px row) with the toggle group right-aligned inside the second — <strong>exactly</strong> TableListing&#39;s toolbar arrangement, so the same nesting is used.</p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-primary</code></td><td>root, rooms, toolbar <code>background-color</code></td><td></td></tr><tr><td><code>--ai-border-secondary</code></td><td>root <code>border</code>, bar + rooms <code>border-block-end</code>, divider <code>background-color</code></td><td></td></tr><tr><td><code>--ai-radius-lg</code></td><td>root <code>border-radius</code> (16px)</td><td></td></tr><tr><td><code>--ai-radius-md</code></td><td>mobile global-action buttons (from <code>btn--sm</code>)</td><td></td></tr><tr><td><code>--ai-radius-sm</code></td><td>kebab focus ring radius</td><td></td></tr><tr><td><code>--ai-spacing-6</code></td><td>bar <code>padding</code>, rooms + toolbar <code>padding-inline</code> (24px)</td><td></td></tr><tr><td><code>--ai-spacing-5</code></td><td>rooms + toolbar <code>padding-block</code>, rooms + toolbar <code>gap</code>, divider <code>block-size</code> (16px)</td><td></td></tr><tr><td><code>--ai-spacing-4</code></td><td>title-row <code>gap</code>, meta <code>column-gap</code>, mobile bar <code>gap</code> + <code>padding-inline</code>, mobile rooms + toolbar <code>padding</code> (12px)</td><td></td></tr><tr><td><code>--ai-spacing-3</code></td><td>details <code>gap</code>, actions <code>gap</code>, room <code>gap</code>, toggle-group <code>gap</code>, buttons <code>gap</code>, mobile rooms <code>gap</code>, <strong>mobile toolbar <code>gap</code></strong> (8px)</td><td></td></tr><tr><td><code>--ai-spacing-2</code></td><td>meta <code>row-gap</code>, meta-item <code>gap</code>, compact-toolbar buttons <code>gap</code> (6px)</td><td></td></tr><tr><td><code>--ai-spacing-0-5</code></td><td>compact-toolbar room <code>gap</code> (2px)</td><td>Figma binds <code>--ai-spacing-1</code> — see below</td></tr><tr><td><code>--ai-spacing-7</code></td><td><strong>bar <code>gap</code> (32px)</strong>, compact export button + mobile global-action <code>min-height</code></td><td></td></tr><tr><td><code>--ai-size-5</code></td><td>desktop room-card <code>flex-basis</code> (280px)</td><td>Figma draws 290 — see below</td></tr><tr><td><code>--ai-font-title</code></td><td>every text node</td><td></td></tr><tr><td><code>--ai-font-fixed-xl</code> / <code>-md</code></td><td>title, desktop / mobile (22 / 18px)</td><td></td></tr><tr><td><code>--ai-font-fixed-md</code> / <code>-sm</code></td><td>room name, desktop / mobile (18 / 16px)</td><td></td></tr><tr><td><code>--ai-font-fixed-xs</code> / <code>-2xs</code></td><td>meta items + room count, desktop / mobile (14 / 12px)</td><td></td></tr><tr><td><code>--ai-font-fixed-xxs</code></td><td>&quot;Show unassigned&quot; (12px, both breakpoints)</td><td></td></tr><tr><td><code>--ai-font-fluid-xxs</code></td><td>mobile global-action font size (from <code>btn--sm</code>)</td><td></td></tr><tr><td><code>--ai-font-bold</code> / <code>-medium</code></td><td>title + room name / meta + count + toggle label</td><td></td></tr><tr><td><code>--ai-text-primary</code> / <code>--ai-text-contrast</code></td><td>title + room name / meta + count + toggle label</td><td></td></tr><tr><td><code>--ai-leading-xs</code></td><td>meta items (16px)</td><td></td></tr><tr><td><code>--ai-icon-size-sm</code></td><td>meta icons (16px)</td><td></td></tr><tr><td><code>--ai-icon-size-md</code></td><td>kebab (20px)</td><td></td></tr><tr><td><code>--ai-icon-size-xs</code></td><td>swap button icon (12px, from <code>btn--xs</code>)</td><td></td></tr><tr><td><code>--ai-icon-contrast</code></td><td>meta icons</td><td></td></tr><tr><td><code>--ai-icon-secondary</code></td><td>kebab</td><td><strong>a different icon colour — see below</strong></td></tr><tr><td><code>--ai-surface-brand</code></td><td>kebab <code>:focus-visible</code> outline</td><td></td></tr></tbody></table><h3 id="two-different-icon-colours-in-one-component" tabindex="-1">Two different icon colours in one component <a class="header-anchor" href="#two-different-icon-colours-in-one-component" aria-label="Permalink to &quot;Two different icon colours in one component&quot;">​</a></h3><p>The three meta icons are <code>--ai-icon-contrast</code> (#94a3b8); the kebab is <code>--ai-icon-secondary</code> (#64748b). Both appear in the variant&#39;s variable list, so they were disambiguated with scoped <code>get_variable_defs</code> calls on <code>3474:90247</code> and <code>3515:330387</code> rather than guessed. Worth a designer glance — a one-step difference between two icons in the same header may be intentional (the kebab is interactive, the meta icons are decoration) or may be drift.</p><h2 id="token-gaps-and-decisions" tabindex="-1">Token gaps and decisions <a class="header-anchor" href="#token-gaps-and-decisions" aria-label="Permalink to &quot;Token gaps and decisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>Decision</th></tr></thead><tbody><tr><td>root <code>w-[1552px]</code>, <code>Event-Details</code> <code>w-[900px]</code> — both unbound, matching no <code>--ai-size-*</code> token</td><td><strong>Both fluid</strong> (designer, 2026-08-26): root <code>inline-size: 100%</code>, details <code>flex: 1 0 0</code> + <code>min-inline-size: 0</code>. The bar is <code>justify-between</code>, so the details block is simply its left column, and 1552/900 are just the frame Figma drew. Same call already taken for AttendeeCard, TableCard and TableListing.</td></tr><tr><td>Room Card instance <code>w-[290px]</code> (desktop)</td><td><strong><code>--ai-size-5</code></strong> (280px). 290 has no token; 280 is the one that exists <strong>and is the <code>min-inline-size</code> RoomCard itself binds</strong> — the identical call made when RoomCard was built, so the two components agree rather than disagree by 10px.</td></tr><tr><td>Toolbar room-label <code>gap-[8px]</code>, unbound</td><td><strong><code>--ai-spacing-3</code></strong>, which is exactly 8px, so binding it is visually a no-op. Same treatment as TableListing&#39;s 12px filter label. <strong>Worth binding in Figma.</strong></td></tr><tr><td><code>Event-Info-Bar</code> has no gap (Figma relies on <code>space-between</code> against a fixed 900px block)</td><td><strong><code>--ai-spacing-7</code></strong> (32px) added (designer, 2026-08-26). With the details block fluid, this gap is what replaces the fixed width and keeps a long event title off the buttons. Overridden to <code>--ai-spacing-4</code> in the stacked mobile layout.</td></tr><tr><td>Figma&#39;s mobile <code>Toolbar-Actions</code> room block binds <code>gap: --ai-spacing-1</code> (4px)</td><td><strong><code>--ai-spacing-0-5</code></strong> (2px) below 1024px (designer, 2026-08-26). Two lines of stacked text read as one block at 2px and as two separate things at 4px. The identical tightening was taken on TableDetail&#39;s legend row gap, so it is a consistent preference rather than a one-off. <code>--ai-spacing-1</code> is now unused in this component.</td></tr><tr><td>Figma&#39;s mobile <code>Toolbar</code> binds <code>gap: --ai-spacing-5</code> (16px)</td><td><strong><code>--ai-spacing-3</code></strong> (8px) below 768px (designer, 2026-08-26) — a deliberate override rather than a Figma value. Scoped to the 767px block, so the 768–1023 tablet band keeps Figma&#39;s 16px. It is the gap between the actions group and the kebab.</td></tr><tr><td>Kebab is a bare <code>Icon/24px/EllipsisVertical</code> layer, not a Button instance</td><td><strong>Built as a real <code>&lt;button&gt;</code></strong> (designer, 2026-08-26) with <code>aria-label=&quot;More seating actions&quot;</code> and a stretched <code>::after</code> giving the 44×44 touch target, while the icon stays 20px as drawn. A bare <code>&lt;i&gt;</code> is neither focusable nor keyboard-operable (CLAUDE.md §9). Same stretched-trigger pattern RoomCard uses.</td></tr><tr><td>Divider <code>line</code> node stroke, invisible in design context</td><td><strong><code>--ai-border-secondary</code></strong>, resolved by <code>get_variable_defs</code> on the node itself (<code>3474:90290</code>). Not a gap — the same element, and the same resolution, as TableListing&#39;s divider.</td></tr></tbody></table><h3 id="text-22px-is-not-a-gap-—-design-context-under-reported-it" tabindex="-1"><code>text-[22px]</code> is NOT a gap — design context under-reported it <a class="header-anchor" href="#text-22px-is-not-a-gap-—-design-context-under-reported-it" aria-label="Permalink to &quot;\`text-[22px]\` is NOT a gap — design context under-reported it&quot;">​</a></h3><p>The desktop title reads as a raw <code>text-[22px]</code> in <code>get_design_context</code>, which looks like an unbound value. But <code>get_variable_defs</code> on the variant lists <strong><code>--ai-font-fixed-xl: 22</code></strong>, and nothing else in the variant is 22px — so the title <em>is</em> bound and the design context simply did not report it.</p><p>Worth recording as a method note: <strong>a raw-looking value in design context is not evidence of an unbound value.</strong> Cross-check <code>get_variable_defs</code> before raising a token gap. The same under-reporting was hit earlier in this module.</p><h2 id="device-mobile-deltas" tabindex="-1">Device=Mobile deltas <a class="header-anchor" href="#device-mobile-deltas" aria-label="Permalink to &quot;Device=Mobile deltas&quot;">​</a></h2><blockquote><p><strong>Read with the breakpoint section below.</strong> The rows from <code>__room</code> down are <em>toolbar</em> rows, and they now apply from <strong>1023px</strong>, not 767px — so they are already in effect at tablet widths.</p></blockquote><table tabindex="0"><thead><tr><th>Property</th><th>Desktop</th><th>Mobile</th></tr></thead><tbody><tr><td><code>__bar</code> direction</td><td><code>row</code>, <code>justify-content: space-between</code></td><td><strong><code>column</code></strong>, three stacked rows, gap <code>--ai-spacing-4</code></td></tr><tr><td><code>__bar</code> padding</td><td><code>--ai-spacing-6</code> all round (24)</td><td><strong><code>--ai-spacing-4</code> inline / <code>--ai-spacing-5</code> block</strong> (12/16) — asymmetric, <em>not</em> a step-down</td></tr><tr><td><code>__title</code></td><td>22px, <code>flex: 0 1 auto</code>, ellipsis</td><td>18px, <code>flex: 1 0 0</code>, <strong>wraps</strong> (<code>overflow-wrap: break-word</code>)</td></tr><tr><td><code>__title-row</code> align</td><td><code>center</code></td><td><code>flex-start</code></td></tr><tr><td><code>__meta</code></td><td>one row</td><td><strong>wraps to two</strong> (date + attendees, then venue)</td></tr><tr><td><code>__meta-item</code> font</td><td>14px</td><td>12px</td></tr><tr><td><code>__actions</code> order</td><td>secondary, then primary</td><td><strong>primary first</strong> — see below</td></tr><tr><td><code>__actions</code> button size</td><td>base (40 tall)</td><td><code>btn--sm</code> (32 tall)</td></tr><tr><td><code>__rooms</code> padding / gap</td><td>24/16, gap 16</td><td>12 all round, gap 8</td></tr><tr><td>room cards</td><td><code>flex: 0 0 280px</code></td><td><code>flex: 1 0 0</code> on RoomCard&#39;s own 240px floor</td></tr><tr><td><code>__toolbar</code> padding</td><td>24 inline / 16 block</td><td>12 all round</td></tr><tr><td><code>__toolbar</code> gap</td><td><code>--ai-spacing-5</code> (16)</td><td><strong><code>--ai-spacing-3</code> (8)</strong> — a designer call, not Figma; see below</td></tr><tr><td><code>__room</code> direction</td><td><code>row</code>, gap 8</td><td><strong><code>column</code></strong>, gap <strong>2</strong> (Figma draws 4)</td></tr><tr><td><code>__room-name</code> / <code>__room-count</code></td><td>18 / 14px</td><td>16 / 12px</td></tr><tr><td><code>__toggle-group</code>, <code>__divider</code></td><td>present</td><td><strong><code>display: none</code></strong> — absent from the variant, not rearranged</td></tr><tr><td><code>__buttons</code> gap</td><td>8</td><td>6</td></tr><tr><td>Room Layout button</td><td>present</td><td><strong>hidden</strong></td></tr><tr><td>Add Table button</td><td>&quot;Add Table&quot;</td><td><strong>&quot;Add&quot;</strong></td></tr><tr><td>Export button</td><td>icon + text + chevron (111×32)</td><td><strong>icon only, 32×32</strong></td></tr></tbody></table><h3 id="three-of-those-deltas-are-content-not-styling" tabindex="-1">Three of those deltas are content, not styling <a class="header-anchor" href="#three-of-those-deltas-are-content-not-styling" aria-label="Permalink to &quot;Three of those deltas are content, not styling&quot;">​</a></h3><p>Figma&#39;s mobile toolbar has <strong>two</strong> buttons where desktop has three: <code>Room Layout</code> is gone, <code>Add Table</code> reads <code>Add</code>, and <code>Export</code> is icon-only. Read off the mobile screenshot, not guessed — the 64×32 and 32×32 geometry alone would not have identified which buttons survived.</p><p>They are handled in CSS rather than by shipping two markups:</p><ul><li><code>Room Layout</code> → <code>display: none</code>.</li><li>The dropped words (<code>&quot; Table&quot;</code>, <code>&quot;Export&quot;</code>) are wrapped in <code>.seating-header__btn-shrink</code> and <strong>clipped</strong> with <code>clip-path: inset(50%)</code>, not <code>display: none</code>, so the full label stays in the accessibility tree and the icon-only export button keeps an accessible name. Same technique RoomCard uses to drop the word &quot;seated&quot;. Being out of flow, they contribute no flex gap.</li><li><strong><code>Add Table</code>&#39;s label is wrapped in a single <code>.seating-header__btn-label</code> span</strong>, which carries no CSS and exists purely for layout: <code>.btn</code> is a flex container with its own gap, so leaving <code>Add</code> and <code>&lt;span&gt; Table&lt;/span&gt;</code> as two separate children rendered <strong>&quot;Add  Table&quot;</strong> — the button&#39;s gap <em>plus</em> the span&#39;s leading space. Caught by looking at the render, not by measuring. Export needs no such wrapper: its text is one child between two icons, which is exactly the spacing Figma draws.</li><li>The export button gets <code>btn--icon btn--sm</code>&#39;s 32×32 geometry inline, and the two global-action buttons get <code>btn--sm</code>&#39;s four geometry properties, because <strong>a size class cannot be added from a media query</strong>.</li></ul><h3 id="the-mobile-button-order-is-reversed-—-worth-confirming" tabindex="-1">The mobile button order is reversed — worth confirming <a class="header-anchor" href="#the-mobile-button-order-is-reversed-—-worth-confirming" aria-label="Permalink to &quot;The mobile button order is reversed — worth confirming&quot;">​</a></h3><p>Desktop leads with the secondary <code>Copy Plans</code> (x=0) and puts the primary <code>New Plan</code> second. Mobile puts <strong><code>New Plan</code> first</strong> (x=0) and <code>Copy Plans</code> second — confirmed on both the node positions and the rendered screenshot, so it is not a misreading.</p><p>Built as drawn, via <code>order: -1</code> on the primary at mobile. <strong>Flagged because it may be a layer-order slip rather than a decision.</strong> Leading with the primary CTA on a phone is a recognised pattern, so it may well be deliberate — but it does mean the visual order and the DOM/tab order disagree at one breakpoint, and there is no way to satisfy both without shipping two markups. DOM order follows desktop.</p><h2 id="the-room-selector-is-a-carousel-with-no-scrollbar" tabindex="-1">The room selector is a carousel, with no scrollbar <a class="header-anchor" href="#the-room-selector-is-a-carousel-with-no-scrollbar" aria-label="Permalink to &quot;The room selector is a carousel, with no scrollbar&quot;">​</a></h2><p>Figma&#39;s <strong>own mobile variant overflows its own frame</strong>: 12 + 240 + 8 + 240 + 12 = 512 in a 392px frame, with the second card visibly clipped in the screenshot. So &quot;more plans than fit&quot; is the drawn state, and a horizontal scroller is the faithful reading of it — the alternative would be to invent wrapping Figma does not show.</p><p><strong>No scrollbar</strong> (designer, 2026-08-26). This is <em>closer</em> to Figma than the thin bar it replaced: Figma draws the second card simply clipped, with no scrollbar anywhere. It is deliberately <strong>not</strong> the treatment TableDetail&#39;s seat list has — that is a long vertical list where the bar doubles as a position indicator worth keeping, whereas a two-or-three-card horizontal carousel is a different interaction. Removing it also brought the rendered mobile height from 335px to <strong>320px</strong> against Figma&#39;s 317.</p><p>Only the <em>bar</em> is hidden; scrolling itself is untouched. So the three input paths are:</p><table tabindex="0"><thead><tr><th>Input</th><th>How</th><th>Needs JS?</th></tr></thead><tbody><tr><td><strong>Touch</strong></td><td>native swipe, with the platform&#39;s own momentum and rubber-banding</td><td><strong>No</strong> — and deliberately not reimplemented, which is how carousels end up feeling wrong</td></tr><tr><td><strong>Mouse</strong></td><td>click-and-drag, <code>cursor: grab</code></td><td><strong>Yes</strong> — <code>SeatingHeader.js</code>; no browser does this natively</td></tr><tr><td><strong>Keyboard</strong></td><td>Tab to a card and focus scrolls it into view</td><td><strong>No</strong></td></tr></tbody></table><p>The rail is deliberately <strong>not</strong> given a <code>tabindex</code>. The cards inside are real <code>&lt;button&gt;</code>s, so the keyboard path already works, and a focusable rail would add a stop that announces nothing.</p><p><code>is-scrollable</code> (and so the grab cursor) is applied <strong>only when the content actually overflows</strong>, so a bar holding one plan does not advertise a drag that goes nowhere. It is kept in sync on resize and on plan add/remove — a <code>MutationObserver</code>, because adding a card resizes nothing (the rail is already full width) and a <code>ResizeObserver</code> alone would miss it. Both are coalesced to one pass per frame, since <code>scrollWidth</code> forces layout and <code>lucide.createIcons()</code> alone fires ~40 mutations at startup.</p><h3 id="two-things-the-drag-has-to-get-right" tabindex="-1">Two things the drag has to get right <a class="header-anchor" href="#two-things-the-drag-has-to-get-right" aria-label="Permalink to &quot;Two things the drag has to get right&quot;">​</a></h3><ol><li><strong>A drag must not activate what it ends on.</strong> Every card is a select trigger and carries edit/delete buttons, so a 200px drag finishing over &quot;Delete&quot; must not delete anything. A 5px movement threshold separates the two: under it the press stays an ordinary click, over it the click is swallowed in the <strong>capture</strong> phase, before the card&#39;s own handlers run. The suppression flag is cleared on the next <code>pointerdown</code> <em>and</em> after being used, rather than on a timer — a drag released outside the window fires no click at all, and a timer-cleared flag would still be set when the user&#39;s next genuine click arrived.</li><li><strong><code>preventDefault()</code> is not called on <code>pointerdown</code>.</strong> It would stop the card buttons taking focus and break the keyboard path. Text selection is suppressed with <code>user-select</code> during the drag instead.</li></ol><p><code>overscroll-behavior-x: contain</code> stops a swipe past the end chaining to the page, which on iOS and in Chrome otherwise triggers back-navigation.</p><p>Verified: drag moves <code>scrollLeft</code> by exactly the pointer delta; a 2px press still clicks; a click straight after a drag does not fire the card&#39;s handler while the next one does; and a <code>touch</code> pointer is ignored entirely, leaving native scrolling alone.</p><p><code>flex-basis</code> is used rather than <code>inline-size</code> on the cards because RoomCard sets its own <code>inline-size: 100%</code>, which as a flex item would otherwise resolve against the whole bar.</p><h2 id="the-toolbar-has-its-own-breakpoint-1024px" tabindex="-1">The toolbar has its own breakpoint: 1024px <a class="header-anchor" href="#the-toolbar-has-its-own-breakpoint-1024px" aria-label="Permalink to &quot;The toolbar has its own breakpoint: 1024px&quot;">​</a></h2><p>Everything else reverts to the desktop layout at 768px, but <strong>the toolbar keeps its compact form up to 1023px</strong> (designer, 2026-08-26). It carries far more than the bars above it — room name, unassigned count, the switch, a divider, three buttons and the kebab — so it runs out of room long before the event bar does.</p><p><strong>1024 is not invented.</strong> It is the Seating Planner shell&#39;s own layout boundary: the prototype&#39;s <code>SeatingPlannerShell.css</code> switches to the worklist at <code>max-width: 1023px</code>, so the DS pattern now changes shape at the same width as the app it belongs to.</p><p>So there are <strong>three</strong> bands, not two — and the middle one is a state neither Figma variant shows, which is why the demo previews it at 900px:</p><table tabindex="0"><thead><tr><th></th><th>&lt; 768</th><th>768–1023</th><th>≥ 1024</th></tr></thead><tbody><tr><td>event bar</td><td>column, 12/16 padding, 18px title</td><td><strong>row, 24 padding, 22px title</strong></td><td>row, 24 padding, 22px title</td></tr><tr><td>room label</td><td>stacked, 16px</td><td><strong>stacked, 16px</strong></td><td>row, 18px</td></tr><tr><td>toggle + divider</td><td>hidden</td><td><strong>hidden</strong></td><td>visible</td></tr><tr><td>toolbar buttons</td><td>2 (Add, icon Export)</td><td><strong>2 (Add, icon Export)</strong></td><td>3 (Room Layout, Add Table, Export)</td></tr><tr><td>inline padding</td><td>12 everywhere</td><td><strong>24 everywhere</strong></td><td>24 everywhere</td></tr></tbody></table><p><strong>The toolbar&#39;s <code>padding</code> deliberately stays in the 767px block</strong>, not the 1023px one. Moving it would indent the toolbar 12px against the event bar&#39;s 24px between 768 and 1023, which reads as a misalignment defect rather than a compact layout. Verified aligned at 800px and 900px (<code>padding-left: 24px</code> on both regions). <strong>Easy to change if the tighter padding is actually wanted.</strong></p><h2 id="border-handling" tabindex="-1">Border handling <a class="header-anchor" href="#border-handling" aria-label="Permalink to &quot;Border handling&quot;">​</a></h2><p>Only <code>Event-Info-Bar</code> and <code>Room-Selector-Bar</code> carry a <code>border-b</code> in Figma; <code>Toolbar</code> has none. That works out on <code>Has Plans</code>, where the toolbar is last — but on <strong><code>No Plans</code> the bar IS last</strong>, and its rule would sit directly on top of the root&#39;s own border, reading as a 2px line at the rounded bottom edge. Suppressed with <code>.seating-header &gt; :last-child { border-block-end: 0 }</code>, so the rule always does its actual job of separating a bar from what follows.</p><h2 id="interaction-model" tabindex="-1">Interaction model <a class="header-anchor" href="#interaction-model" aria-label="Permalink to &quot;Interaction model&quot;">​</a></h2><ul><li><strong>The toggle flips itself</strong> — <code>Toggle</code> gained <code>Toggle.js</code> on 2026-08-26, so the component owns its own <code>.toggle--active</code> and <code>aria-checked</code>. This page just includes the script. Verified: click flips and restores, and clicking the &quot;Show unassigned&quot; text flips it too via <code>label[for]</code> + <code>aria-labelledby</code>.</li><li><strong>Showing/hiding the unassigned tray is deliberately absent.</strong> That belongs to the parent module — a consumer listens for <code>toggle:change</code> and reads <code>detail.active</code>.</li><li><strong>Everything else is presentational.</strong> Switching event, copying plans, creating a plan, selecting a room, the room layout / add table / export actions and the kebab menu are all the parent&#39;s job. RoomCard brings its own selection contract; the parent toggles <code>--selected</code> on it.</li><li>The kebab and the swap button are real <code>&lt;button&gt;</code>s with <code>aria-label</code>s, since neither has visible text.</li><li><code>__meta</code> is a real <code>&lt;ul&gt;</code>, so the three event facts are a list to a screen reader too.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Measured in headless Chrome at 1600px, and at a <strong>true 390px viewport via an iframe</strong> — note that <code>--window-size=390</code> does <em>not</em> work, because Chrome enforces a ~500px minimum window width and silently reports <code>innerWidth: 500</code>. An early mobile pass was measured at 500px because of it.</p><table tabindex="0"><thead><tr><th></th><th>Figma</th><th>Rendered</th><th></th></tr></thead><tbody><tr><td>swap button</td><td>32×24, icon 12×12</td><td><strong>32×24, 12×12</strong></td><td>exact — <code>btn--icon btn--xs</code></td></tr><tr><td>Toggle track / knob</td><td>32×16 / 12×12</td><td><strong>32×16 / 12×12</strong></td><td>exact — <code>toggle--xs</code> needed no change</td></tr><tr><td>divider</td><td>1×16 <code>--ai-border-secondary</code></td><td><strong>1×16, #e2e8f0</strong></td><td>exact</td></tr><tr><td>kebab</td><td>20×20 <code>--ai-icon-secondary</code></td><td><strong>20×20, #64748b</strong></td><td>exact</td></tr><tr><td>meta icons</td><td>16×16 <code>--ai-icon-contrast</code></td><td><strong>16×16, #94a3b8</strong></td><td>exact</td></tr><tr><td>mobile <code>__details</code></td><td>368×70</td><td>364×<strong>70</strong></td><td>height exact</td></tr><tr><td>mobile <code>__meta</code></td><td>368×38 (2 rows)</td><td>364×<strong>38</strong>, 2 rows</td><td>height exact</td></tr><tr><td>mobile global buttons</td><td>103×32 / 114×32</td><td>104×32 / 115×32</td><td>1px</td></tr><tr><td>mobile <code>__bar</code></td><td>392×146</td><td>388×<strong>147</strong></td><td>1px (border)</td></tr><tr><td>mobile <code>__toolbar</code></td><td>392×62</td><td>388×<strong>63</strong></td><td>1px (border)</td></tr><tr><td>desktop root</td><td>1552×288</td><td>1552×<strong>291</strong></td><td>+3px border arithmetic</td></tr><tr><td>desktop <code>__bar</code></td><td>1552×99</td><td>1550×<strong>98</strong></td><td>1px</td></tr><tr><td>mobile root</td><td>392×317</td><td>390×<strong>320</strong></td><td>+3, once the scrollbar gutter went. Was 335 with the bar</td></tr><tr><td>mobile <code>__rooms</code></td><td>392×109</td><td>388×<strong>111</strong></td><td>2px — RoomCard&#39;s own 1px on each card</td></tr></tbody></table><p>Desktop toolbar/global button <em>widths</em> run 4–9px wider than Figma (126.7 vs 118, 134.3 vs 128). That is text metrics in a headless render, not layout — every height is exact and the mobile widths land within 1px.</p><p>Also verified: all 12 Lucide names resolve (37 <code>&lt;svg&gt;</code>s, zero unconverted <code>&lt;i&gt;</code>s), no horizontal page overflow at either width, and the kebab is a focusable <code>BUTTON</code>.</p><h2 id="notes-and-things-to-raise" tabindex="-1">Notes and things to raise <a class="header-anchor" href="#notes-and-things-to-raise" aria-label="Permalink to &quot;Notes and things to raise&quot;">​</a></h2><ul><li><strong><code>Icon</code> is the layer name for all three meta icons</strong>, so their identities are not in the metadata at all — <code>calendar</code>, <code>users</code> and <code>map-pin</code> were read off a screenshot. Worth naming those layers <code>Icon/16px/Calendar</code> etc., as the rest of the module does, so the next build does not need a picture.</li><li><strong>Figma&#39;s <code>Icon/24px/Export</code> has no Lucide equivalent by that name.</strong> Built as <code>download</code>, which is what <code>FilterBar</code> already uses for its own Export button — the house precedent.</li><li><strong>Code Connect omits the size class on two instances.</strong> The 32×24 swap button emits <code>btn btn--secondary btn--icon</code> with no <code>btn--xs</code>, and the base-size Global-Actions buttons emit no size either. The geometry resolved both unambiguously (<code>.btn--icon.btn--xs</code> <em>is</em> 32×24), but the mapping is incomplete. It does correctly resolve <code>btn--sm</code> and primary/secondary elsewhere.</li><li><strong>A single-child <code>Item</code> frame</strong> wraps the desktop meta list, carrying its own <code>--ai-spacing-5</code> gap that does nothing with one child. Dropped. The mobile variant has no such wrapper, which is what confirms it is noise rather than structure — the same one-child-wrapper pattern already dropped in Unassigned and noted in TableDetail.</li><li><strong>The desktop title carries <code>shrink-0</code> together with ellipsis rules</strong> — an inert pair, since a box that cannot shrink never truncates. It only made sense against the fixed 900px parent. With the block now fluid the ellipsis is honoured (<code>flex: 0 1 auto</code>), which is what the rules were there to express.</li><li><strong>The swap button needs its own <code>flex-shrink: 0</code>.</strong> It sits directly in the title row rather than in a group, so unlike <code>__actions</code>, <code>__buttons</code> and <code>__more</code> — whose containers all carry it — it was an ordinary shrinkable flex item. Because <code>.btn--icon</code> sets <code>width</code> rather than a minimum, a long event title crushed it well below its 32px instead of truncating itself. Figma has the instance at a fixed 32×24. Fixed 2026-08-26; verified 32×24 with a 12×12 icon at 1552, 1100, 900, 700, 500, 390 and 320px, with the title ellipsising on desktop and wrapping below 768 instead.</li><li><strong><code>Frame 248</code> / <code>Frame 252</code> are the layer names</strong> for the room-label group and the mobile button group. Default Figma names; worth renaming, and the same layer-naming noise flagged on TableCard, TableDetail and Unassigned.</li><li><strong>The <code>Toolbar</code> frame has no bottom border</strong> while both bars above it do — verified, not assumed.</li><li><strong>No hover, focus, pressed or disabled variants</strong> for the pattern itself, and no dark-mode variant.</li><li><strong><code>get_design_context</code> on a full variant expands every RoomCard.</strong> Fetch <code>Event-Info-Bar</code> (<code>3474:90242</code>), <code>Room-Selector-Bar</code> (<code>3474:90271</code>) and <code>Toolbar</code> (<code>3474:90282</code>) separately.</li><li><strong>Figma MCP has a per-seat tool-call limit</strong> that was hit partway through this build. Scoped <code>get_variable_defs</code> calls and screenshots are the cheap way to resolve values hidden inside SVG assets; a full-variant <code>get_design_context</code> is the expensive one.</li></ul><hr><h2 id="responsive-container-queries-2026-08-27" tabindex="-1">Responsive: container queries (2026-08-27) <a class="header-anchor" href="#responsive-container-queries-2026-08-27" aria-label="Permalink to &quot;Responsive: container queries (2026-08-27)&quot;">​</a></h2><p><strong>Self-container.</strong> <code>.seating-header</code> sets <code>container-type: inline-size; container-name: seating-header</code>, and both former media queries — the 767 mobile block and the 1023 toolbar band — now key on it. Correct as a self-container because this pattern spans the page column, so its own inline size <em>is</em> the available width.</p><p><strong>Two intrinsic fixes, independent of any breakpoint.</strong> <code>.seating-header__room-name</code> and <code>__room-count</code> had <code>white-space: nowrap</code> with no ellipsis and no zero min-size, so they could not shrink and simply spilled out of their flex parent — measured a 130px box holding 243px of text, running over the Show-unassigned toggle. Both now truncate. The container query stacks that row far earlier now, but the guard matters at every width, which a breakpoint alone would not give.</p><p>Rationale and the decision rule live in <strong>CLAUDE.md §4a</strong>. The short version: a docked SidebarMenu shrinks the CC content column with no window resize, so a viewport query cannot see the real available width — measured 820px of column at a 2239px viewport, with no query firing.</p><h3 id="room-cards-are-capped-2026-08-27" tabindex="-1">Room cards are capped (2026-08-27) <a class="header-anchor" href="#room-cards-are-capped-2026-08-27" aria-label="Permalink to &quot;Room cards are capped (2026-08-27)&quot;">​</a></h3><p>The narrow block sets <code>.seating-header__rooms &gt; .room-card { flex: 1 0 0 }</code>, which Figma draws so a single plan fills the row while two or more hold RoomCard&#39;s 240px mobile floor and scroll. With no maximum that was harmless while the block only fired on a phone — but it now fires on <strong>container</strong> width, so a squeezed desktop column produced one absurdly wide plan chip.</p><p><code>max-inline-size: var(--ai-size-6)</code> (320) caps it. 320 sits just above Figma&#39;s mobile card (302), so a real phone still fills the row exactly as drawn — verified at a genuine 402px viewport: one plan renders 285px in a 285px row, four plans render 240px each and the carousel scrolls (1008 vs 309). The cap only engages once the row is wider than the design ever intended.</p><p><strong>Flagged:</strong> if plans should never exceed their 280px desktop pin, this becomes <code>--ai-size-5</code> — a one-token change. 320 was chosen to preserve the mobile frame&#39;s fill; neither token is Figma&#39;s 302.</p><h3 id="the-header-must-never-shrink-fixed-2026-08-27" tabindex="-1">The header must never shrink (fixed 2026-08-27) <a class="header-anchor" href="#the-header-must-never-shrink-fixed-2026-08-27" aria-label="Permalink to &quot;The header must never shrink (fixed 2026-08-27)&quot;">​</a></h3><p>Reported: &quot;planner header all broken, no plan showing and height cropping content.&quot; Reproduced and measured inside the Seating Planner — at a 402px column the header rendered <strong>2px</strong> against a natural 251, so the room carousel was 25px and the toolbar and half the action buttons were simply gone. At 700px it rendered 101 of 211, which is the sliced-buttons screenshot.</p><p><strong>The component itself was never at fault</strong> — its own demo measured a correct 299px (bar 125 + rooms 112 + toolbar 60) with both room cards visible, because there the parent is <code>display: block</code> and nothing can shrink it. The failure only appears where it is a flex item.</p><p><strong>Mechanism, and the part worth remembering.</strong> <code>.cc-control__page</code> is a height-constrained flex column. SeatingPlanner had just been changed to <code>.seating-plan { flex: 0 0 auto }</code> so the stacked row could take its natural height and let the page scroll — but <code>flex-shrink: 0</code> means the row refuses to give anything back, so when the column ran short the <strong>entire</strong> shortfall (1026px at mobile) had to come out of the only shrinkable sibling: this header, at its default <code>flex: 0 1 auto</code>.</p><p>The usual protection did not apply, and that is the subtle bit: a flex item&#39;s automatic minimum size (<code>min-height: auto</code>) <strong>only protects items whose <code>overflow</code> is <code>visible</code></strong>. This root sets <code>overflow: hidden</code> to keep the room carousel inside its radius, so its automatic minimum is <strong>zero</strong> — it collapsed all the way and clipped, rather than refusing to shrink.</p><p>Fix: <code>flex-shrink: 0</code> on <code>.seating-header</code>. A header&#39;s height is its content, and crushing it destroys information rather than tightening it; with this the overflow goes to the scroll container instead, which is the correct failure mode. Inert in the standalone demo, where the parent is not a flex container.</p><p><strong>A hypothesis worth recording as wrong:</strong> the obvious suspect was <code>container-type: inline-size</code>, since layout containment can zero an automatic minimum size. Tested directly by setting <code>container-type: normal</code> on the live element — the header stayed at 2px. The container query had nothing to do with it.</p><p>Verified after the fix at columns 1800 / 1400 / 1100 / 900 / 700 / 500 / 402: header always at its natural height (294–341), room card always visible, toolbar always present, and all content reachable — the grid scrolling at 1100 and the page scrolling at ≤700.</p><h2 id="toolbar-overlap-and-the-icon-only-add-2026-08-28" tabindex="-1">Toolbar overlap and the icon-only Add (2026-08-28) <a class="header-anchor" href="#toolbar-overlap-and-the-icon-only-add-2026-08-28" aria-label="Permalink to &quot;Toolbar overlap and the icon-only Add (2026-08-28)&quot;">​</a></h2><p>Reported: at small sizes the room label overlapped the Add button; and the principle behind it — <strong>a layout should never overlap, it should reflow.</strong> The designer suspected absolute positioning.</p><p><strong>It was not absolute positioning.</strong> The two <code>position: absolute</code> uses here are a 44×44 touch target on the kebab (a pseudo-element) and the visually-hidden label pattern — neither affects sibling layout. The cause was <code>align-items</code>.</p><h3 id="align-items-becomes-a-width-policy-the-moment-you-flip-to-column" tabindex="-1"><code>align-items</code> becomes a WIDTH policy the moment you flip to column <a class="header-anchor" href="#align-items-becomes-a-width-policy-the-moment-you-flip-to-column" aria-label="Permalink to &quot;\`align-items\` becomes a WIDTH policy the moment you flip to column&quot;">​</a></h3><p><code>.seating-header__room</code> is a row on desktop and a column below 1023. The column block set <code>align-items: flex-start</code>, which reads as harmless alignment — but in a column flex container the cross axis is horizontal, so anything other than <code>stretch</code> <strong>shrink-wraps each child to its own content</strong>. The room name therefore held a fixed 111px while its parent shrank, escaping the box by up to <strong>+72px</strong> and painting over the buttons — a <strong>56px overlap</strong> at a 260px column.</p><p>The <code>overflow: hidden</code> + <code>text-overflow: ellipsis</code> added earlier were present the whole time and could never fire: a shrink-wrapped box is never narrower than its own text.</p><p><code>align-items: stretch</code> fixes it — measured at a 260px column, name 111 → 39, escape +72 → none, 56px overlap → 16px of clearance. Visually identical to <code>flex-start</code>, because the text is left-aligned either way.</p><p><strong>Generalise this:</strong> whenever a rule flips <code>flex-direction</code> to <code>column</code>, re-check <code>align-items</code>. A value that only described alignment in the row layout silently becomes a width policy, and it is precisely why a layout overlaps instead of reflowing.</p><h3 id="add-table-is-icon-only-on-mobile-figma-updated" tabindex="-1">Add Table is icon-only on mobile (Figma updated) <a class="header-anchor" href="#add-table-is-icon-only-on-mobile-figma-updated" aria-label="Permalink to &quot;Add Table is icon-only on mobile (Figma updated)&quot;">​</a></h3><p>Mobile frame <code>3515:213426</code> now draws the buttons group at <strong>96 wide</strong> — two 32×32 icon buttons plus the 20px kebab, down from 128 — and the room block took the 16px it freed, 158 → <strong>190</strong>. So Add joins Export as icon-only.</p><p>There are now three steps, because Figma has only two frames (desktop 1552, mobile 402) and the band between is ours to degrade: <strong>&quot;Add Table&quot; → &quot;Add&quot; (≤1023) → icon (≤767)</strong>. The label is CLIPPED, not removed, so &quot;Add Table&quot; stays the button&#39;s accessible name — verified at every width.</p><h3 id="a-second-overlap-in-hit-targets-rather-than-pixels" tabindex="-1">A second overlap, in hit targets rather than pixels <a class="header-anchor" href="#a-second-overlap-in-hit-targets-rather-than-pixels" aria-label="Permalink to &quot;A second overlap, in hit targets rather than pixels&quot;">​</a></h3><p>While checking the first, hit-testing found the kebab stealing Export&#39;s rightmost ~4px: its 44×44 <code>::after</code>, centred on a 20px button, overhangs 12px each side while Figma&#39;s gap is only 8. Export owned 9 of 10 sampled pixels.</p><p>Reduced to <strong>36 × 44</strong> — 20 + 8 + 8, so it fills the gap on both sides and stops exactly where the neighbour begins. Every button now owns all of its own pixels at both breakpoints.</p><p><strong>Flagged:</strong> 36 is a deliberate deviation from the 44 in CLAUDE.md §9. It still clears WCAG 2.2&#39;s AA target-size minimum (2.5.8, 24×24) — the 44 figure is Apple HIG / WCAG 2.5.5 AAA. The alternative is either overlapping a sibling control or widening Figma&#39;s 8px gap, which is a designer call.</p><h2 id="two-designer-directed-divergences-from-the-mobile-frame-2026-08-28" tabindex="-1">Two designer-directed divergences from the mobile frame (2026-08-28) <a class="header-anchor" href="#two-designer-directed-divergences-from-the-mobile-frame-2026-08-28" aria-label="Permalink to &quot;Two designer-directed divergences from the mobile frame (2026-08-28)&quot;">​</a></h2><p>Both applied on explicit instruction, and both currently differ from what <code>3515:213426</code> draws. Recorded so the next audit reads them as intentional rather than as drift to be corrected back — if the frames are updated to match, delete this section.</p><table tabindex="0"><thead><tr><th>Property</th><th>Code</th><th>Frame <code>3515:213426</code></th><th>How the frame value was read</th></tr></thead><tbody><tr><td><code>.seating-header__meta</code> <code>row-gap</code></td><td><code>--ai-spacing-1</code> (4px)</td><td><strong>6px</strong></td><td>Its three meta items sit at y=0 and y=22 at 16px tall → 22 − 16 = 6</td></tr><tr><td><code>.seating-header__bar</code> <code>gap</code> (mobile)</td><td><code>--ai-spacing-5</code> (16px)</td><td><strong>12px</strong></td><td>Inside the 170px Event-Info-Bar, Event-Details occupies y=16..110 and Global-Actions starts at y=122 → 122 − 110 = 12</td></tr></tbody></table><p>Everything else in the mobile bar still matches the frame: <code>padding-inline</code> 12px and <code>padding-block</code> 16px (block-start reads y=16, block-end reads 170 − 154 = 16), and the asymmetry is real rather than a step-down of the desktop 24.</p><p><code>align-items: flex-start</code> alongside <code>flex-direction: column</code> is only safe because <code>.seating-header__details</code> sets <code>inline-size: 100%</code> two rules below. When the direction flips, <code>align-items</code> stops being a cross-axis alignment and becomes a WIDTH policy — anything but <code>stretch</code> shrink-wraps every child. The explicit width is what neutralises that here; do not remove it while leaving <code>flex-start</code> in place.</p><h3 id="measuring-this-component-there-are-two-seating-header-in-the-seating-planner" tabindex="-1">Measuring this component: there are TWO <code>.seating-header</code> in the Seating Planner <a class="header-anchor" href="#measuring-this-component-there-are-two-seating-header-in-the-seating-planner" aria-label="Permalink to &quot;Measuring this component: there are TWO \`.seating-header\` in the Seating Planner&quot;">​</a></h3><p>One is <code>display: none</code> (the no-plans state) and one is live. An unscoped <code>querySelector(&#39;.seating-header__bar&#39;)</code> returns the hidden one first, which reports <code>width: 0</code>, <code>flex-direction: row</code> and the DESKTOP gap — indistinguishable from &quot;the mobile container query never fired&quot;. That reading cost a diagnosis during this change. Select the first match with a non-zero box, and kill transitions (<code>*{transition:none!important}</code>) because they do not advance under headless Chrome&#39;s <code>--virtual-time-budget</code>.</p><h2 id="the-toolbar-s-add-button-has-two-label-states-not-three-2026-08-28" tabindex="-1">The toolbar&#39;s Add button has TWO label states, not three (2026-08-28) <a class="header-anchor" href="#the-toolbar-s-add-button-has-two-label-states-not-three-2026-08-28" aria-label="Permalink to &quot;The toolbar&#39;s Add button has TWO label states, not three (2026-08-28)&quot;">​</a></h2><p><code>.seating-header__btn--add</code> was degrading in three steps — <strong>&quot;Add Table&quot; → &quot;Add&quot; → icon-only</strong> — because the ≤1023 block clipped <code>.seating-header__btn-shrink</code> unscoped, and that class catches both toolbar buttons while wrapping different content in each:</p><table tabindex="0"><thead><tr><th>Button</th><th>Markup</th><th>Effect of clipping <code>__btn-shrink</code></th></tr></thead><tbody><tr><td>Add</td><td><code>Add&lt;span class=&quot;__btn-shrink&quot;&gt; Table&lt;/span&gt;</code></td><td>leaves the bare word <strong>&quot;Add&quot;</strong></td></tr><tr><td>Export</td><td><code>&lt;span class=&quot;__btn-shrink&quot;&gt;Export&lt;/span&gt;</code></td><td>leaves <strong>nothing</strong> → icon-only</td></tr></tbody></table><p>One selector, two outcomes. The clip is now scoped to <code>.seating-header__btn--export .seating-header__btn-shrink</code>, so Add holds its full label down to 767 and then goes icon-only, matching the only two states Figma draws (desktop 1552, mobile 402).</p><p>The intermediate &quot;Add&quot; was never a design state — it relieved a real overflow in the 768–1023 band back when this pattern used viewport media queries that could not see the docked SidebarMenu narrowing the column. With the self-container reflowing correctly there is nothing to relieve, and a button labelled just &quot;Add&quot; is less clear than either state Figma specifies.</p><p>Measured across the whole band on the live screen, by CONTAINER width (which is what the queries key on, not the viewport):</p><table tabindex="0"><thead><tr><th>container</th><th>Add</th><th>Export</th><th>room ↔ buttons</th></tr></thead><tbody><tr><td>1224</td><td>&quot;Add Table&quot; 108px</td><td>&quot;Export&quot; 112px</td><td>clear 651px</td></tr><tr><td>909 / 833 / 832</td><td>&quot;Add Table&quot; 108px</td><td>icon 32px</td><td>clear 16px</td></tr><tr><td>709 → 269</td><td>icon 32px</td><td>icon 32px</td><td>clear 16px</td></tr></tbody></table><p>No overlap at any width and no horizontal overflow; clearance is a steady 16px from 1100 down.</p><p><strong>Reading that table:</strong> the label is CLIPPED, not <code>display: none</code>, so &quot;Add Table&quot; stays in the accessibility tree at every size and <code>innerText</code> still reports it when the button is visually icon-only. The 32px width is the signal that the label is hidden — do not use text content to test which state the button is in.</p><h2 id="toolbar-tightened-and-its-inline-padding-made-asymmetric-2026-08-28" tabindex="-1">Toolbar tightened, and its inline padding made asymmetric (2026-08-28) <a class="header-anchor" href="#toolbar-tightened-and-its-inline-padding-made-asymmetric-2026-08-28" aria-label="Permalink to &quot;Toolbar tightened, and its inline padding made asymmetric (2026-08-28)&quot;">​</a></h2><p>Designer-directed. Three changes to two rules:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Property</th><th>Was</th><th>Now</th></tr></thead><tbody><tr><td><code>.seating-header__toolbar</code></td><td><code>gap</code></td><td><code>--ai-spacing-5</code> 16px</td><td><code>--ai-spacing-3</code> 8px</td></tr><tr><td><code>.seating-header__toolbar</code></td><td><code>padding-inline-end</code></td><td>(24px, from the shorthand)</td><td><code>--ai-spacing-4</code> 12px</td></tr><tr><td><code>.seating-header__toolbar-actions</code></td><td><code>gap</code></td><td><code>--ai-spacing-5</code> 16px</td><td><code>--ai-spacing-3</code> 8px</td></tr></tbody></table><p><strong>The asymmetric padding relies on declaration order.</strong> <code>padding-inline-end</code> must stay AFTER <code>padding-inline</code>; reversed, the shorthand resets the end side back to 24px. It reads like a redundant pair and is not. It happens to be alphabetical, so a property sorter leaves it alone.</p><p><strong>A ≤767 override became dead and was removed.</strong> That block used to re-declare <code>gap: var(--ai-spacing-3)</code>, scoped there deliberately so the tablet band kept Figma&#39;s 16px. With the base rule now 8px it restated the inherited value, and its comment (&quot;the tablet band keeps Figma&#39;s 16px&quot;) had become false. Its <code>padding: var(--ai-spacing-4)</code> remains real — it flattens the base rule&#39;s 24/12 inline and 16 block into 12px on all four sides, confirmed on mobile frame <code>3515:213426</code> where a 326px Toolbar holds a 302px Toolbar-Actions at x=12.</p><p><strong>FLAGGED:</strong> the <code>__toolbar-actions</code> 8px diverges from that frame, which still draws 16px — its room block occupies x=0..190 and the button cluster starts at x=206. Third such divergence recorded today, alongside the meta row-gap and the bar gap.</p><h3 id="the-8px-gap-halves-the-safety-margin-—-stress-tested-and-it-holds" tabindex="-1">The 8px gap halves the safety margin — stress-tested, and it holds <a class="header-anchor" href="#the-8px-gap-halves-the-safety-margin-—-stress-tested-and-it-holds" aria-label="Permalink to &quot;The 8px gap halves the safety margin — stress-tested, and it holds&quot;">​</a></h3><p>Room ↔ buttons clearance drops from 16px to 8px, a direct consequence of the actions gap. That is now the tightest margin in the toolbar, and this component has a history of overlapping exactly there, so it was tested rather than assumed. With a 60-character room name forced in at five widths:</p><table tabindex="0"><thead><tr><th>viewport</th><th>name box</th><th>its <code>scrollWidth</code></th><th>clipped?</th><th>gap</th><th>hit-test at buttons&#39; left edge</th></tr></thead><tbody><tr><td>1024</td><td>613</td><td>613</td><td>no</td><td>8px</td><td><code>btn</code></td></tr><tr><td>900</td><td>577</td><td>577</td><td>no</td><td>8px</td><td><code>btn</code></td></tr><tr><td>768</td><td>485</td><td>502</td><td><strong>yes</strong></td><td>8px</td><td><code>btn</code></td></tr><tr><td>500</td><td>277</td><td>502</td><td><strong>yes</strong></td><td>8px</td><td><code>btn</code></td></tr><tr><td>390</td><td>167</td><td>502</td><td><strong>yes</strong></td><td>8px</td><td><code>btn</code></td></tr></tbody></table><p>The gap never goes negative, and <code>elementFromPoint</code> at the buttons&#39; leading edge returns the button at every width — the room name never paints over it. Below 768 the name clips with a working ellipsis. So it reflows rather than overlaps, which is the standing requirement for this pattern. <code>elementFromPoint</code> is the check that matters here; reasoning from the cascade is what missed the original overlap.</p><h2 id="toolbar-overflow-menu-the-1200-band-2026-08-28" tabindex="-1">Toolbar overflow menu + the 1200 band (2026-08-28) <a class="header-anchor" href="#toolbar-overflow-menu-the-1200-band-2026-08-28" aria-label="Permalink to &quot;Toolbar overflow menu + the 1200 band (2026-08-28)&quot;">​</a></h2><p>Two new variants on the set (<code>3474:90519</code>, now <strong>6</strong> variants — Type has 4 values):</p><table tabindex="0"><thead><tr><th>Node</th><th>Type</th><th>Frame</th><th>Management-Buttons</th><th>Dropdowns</th></tr></thead><tbody><tr><td><code>3585:110311</code></td><td><code>Menu &gt;1200</code></td><td>1552</td><td><strong>3</strong> — 118 Room Layout, 101 Add, 111 Export</td><td>176×<strong>64</strong>, 1 item</td></tr><tr><td><code>3585:110436</code></td><td><code>Menu &lt;1024</code></td><td>1100</td><td><strong>2</strong> — 101 Add, 111 Export</td><td>176×<strong>96</strong>, 2 items</td></tr></tbody></table><p>The delta is exactly one 32px menu row, so Room Layout is what relocates. Menu items read <strong>Room Layout</strong> and <strong>Table Types</strong>; Table Types is the permanent entry.</p><blockquote><p><strong>These two Types are NOT data.</strong> <code>No Plans</code> / <code>Has Plans</code> are markup the caller picks; these two describe how the toolbar reflows, which is CSS. They are deliberately <strong>not</strong> mapped in <code>SeatingHeader.figma.ts</code> — mapping them would publish a second and third markup for what is one component at different widths.</p></blockquote><h3 id="the-resulting-model" tabindex="-1">The resulting model <a class="header-anchor" href="#the-resulting-model" aria-label="Permalink to &quot;The resulting model&quot;">​</a></h3><table tabindex="0"><thead><tr><th>container</th><th>Room Layout</th><th>Add</th><th>Export</th><th>toggle/divider</th><th>menu</th></tr></thead><tbody><tr><td>≥1200</td><td>toolbar button</td><td>✓</td><td>✓</td><td>shown</td><td>Table Types</td></tr><tr><td>1024–1199</td><td><strong>menu item</strong></td><td>✓</td><td>✓</td><td>shown</td><td>Room Layout, Table Types</td></tr><tr><td>≤1023</td><td>menu item</td><td>✓</td><td>icon</td><td>hidden</td><td>Room Layout, Table Types</td></tr></tbody></table><p>Below 1024 the menu keeps both items and Add/Export stay visible (designer, 2026-08-28) — the mobile layout is unchanged from the existing build.</p><p><strong>Before this, Room Layout was simply lost.</strong> Measured on the old code: at container 1054 it was a 125px button; at 963 it was <code>display: none</code> with nowhere to go, i.e. unreachable. The menu is what makes the collapse non-destructive.</p><p><strong>CSS cannot move a node,</strong> so the button and the menu item are two copies of one action whose visibility swaps. Anything wiring Room Layout must bind BOTH.</p><h3 id="container-queries-measure-the-content-box-—-this-header-s-border-shifts-every-breakpoint-by-2px" tabindex="-1">Container queries measure the CONTENT box — this header&#39;s border shifts every breakpoint by 2px <a class="header-anchor" href="#container-queries-measure-the-content-box-—-this-header-s-border-shifts-every-breakpoint-by-2px" aria-label="Permalink to &quot;Container queries measure the CONTENT box — this header&#39;s border shifts every breakpoint by 2px&quot;">​</a></h3><p><code>max-width: 1199px</code> is correct, but it does not fire at a 1199px <em>element</em>. <code>container-type: inline-size</code> queries the content box, and this root has <code>border: 1px</code> per side:</p><table tabindex="0"><thead><tr><th>border-box</th><th>content box</th><th>Room Layout</th></tr></thead><tbody><tr><td>1202</td><td>1200</td><td>toolbar</td></tr><tr><td><strong>1201</strong></td><td><strong>1199</strong></td><td><strong>menu</strong></td></tr></tbody></table><p>So the switch lands at border-box 1201. The 1023 and 767 blocks carry the same 2px offset and always have, so 1199 was kept rather than compensated — compensating would make this one breakpoint inconsistent with its siblings for a 2px difference nobody can see.</p><p>Worth knowing when measuring: <code>getBoundingClientRect().width</code> is the border box, so a probe will always look 2px out of step with the query. Subtract the border before comparing.</p><h3 id="the-root-s-overflow-hidden-had-to-go" tabindex="-1">The root&#39;s <code>overflow: hidden</code> had to go <a class="header-anchor" href="#the-root-s-overflow-hidden-had-to-go" aria-label="Permalink to &quot;The root&#39;s \`overflow: hidden\` had to go&quot;">​</a></h3><p>Figma draws the panel <strong>48px below the header&#39;s bottom edge</strong> (<code>3585:110311</code>: Toolbar y=224..288 in a 288-tall symbol, Dropdowns y=272..336). An absolutely-positioned panel inside a clipped ancestor is invisible, so the clip was removed.</p><p>It was only ever protecting the radius. The room-selector carousel — the thing the old comment said it was for — clips itself with its own <code>overflow-x: auto</code>. The corners are now held by the first and last rows carrying their own radii, which also survives Type=No Plans where the bar is both. Verified after the change: root <code>overflow: visible</code>, bar top corners 16px, toolbar bottom corners 16px with <code>border-bottom: 0</code>, carousel still scrollable, panel 51px clear of the header.</p><p>That also invalidated the <code>flex-shrink: 0</code> rationale at the top of the file, which cited the clip as the reason <code>min-height: auto</code> could not protect this element. The comment is corrected; the declaration is kept, because stating the intent beats relying on a default that the next <code>overflow</code> change would silently switch off again — which is how the original 2px collapse happened.</p><h3 id="composition-dropdown-not-a-bespoke-menu" tabindex="-1">Composition: Dropdown, not a bespoke menu <a class="header-anchor" href="#composition-dropdown-not-a-bespoke-menu" aria-label="Permalink to &quot;Composition: Dropdown, not a bespoke menu&quot;">​</a></h3><p>The kebab is now a <code>.dropdown__trigger</code> inside a <code>.dropdown</code> root, so open/close, outside-click dismiss, Escape and focus return all come from <code>Dropdown.js</code>. Verified <code>aria-expanded</code> toggles and Escape closes at every width. Dropdown.js does not require its trigger to be a <code>.btn</code>, so the kebab keeps its icon-only look and 36×44 hit area.</p><p>Adds two page requirements: <strong><code>Dropdown.css</code></strong> and <strong><code>Dropdown.js</code> as <code>type=&quot;module&quot;</code></strong>. Both were already on SeatingPlanner.html; both had to be added to this component&#39;s own demo.</p><p>Only two things are set locally — the root must not shrink in the toolbar row, and the panel is flipped to <code>inset-inline-end: 0</code> because Dropdown&#39;s default <code>left: 0</code> would push it off-screen from a trigger at the end of the row.</p><p><strong>FLAGGED — panel size is Dropdown&#39;s, not Figma&#39;s.</strong> Ours renders <strong>240px</strong> wide (Dropdown&#39;s own <code>min-width: var(--ai-size-4)</code>) where Figma&#39;s instance is <strong>176px</strong>; heights are 66/106 against Figma&#39;s 64/96. Figma has resized the Dropdown instance in this context — a contextual override on <em>that</em> component. Not applied here: narrowing Dropdown globally, or scoping an override onto it from this pattern, are both decisions about Dropdown rather than SeatingHeader.</p><p><strong>Both menu actions already exist as prototypes</strong> — this menu is the trigger they never had: <code>seating-room-layout</code> (TASK-344760, <code>SeatingPlannerLayout.js</code>) and <code>seating-table-types</code> (TASK-342308, <code>SeatingPlannerTableTypes.js</code>). So the remaining work is wiring, and persistence is already tracked on those two manifest rows — do not log a third.</p>`,145)])])}const b=t(n,[["render",r]]);export{g as __pageData,b as default};
